deps = {"app": ["feature-transfer", "feature-loan", "feature-ads"],
        "feature-transfer": ["tds", "network"], "feature-loan": ["tds", "network"],
        "feature-ads": ["tds"], "tds": ["core"], "network": ["core"], "core": []}
def rebuild(changed):
    out, todo = {changed}, [changed]
    while todo:
        m = todo.pop()
        for k, v in deps.items():
            if m in v and k not in out:
                out.add(k); todo.append(k)
    return sorted(out)
print(rebuild("feature-ads"))  # ['app', 'feature-ads']
print(rebuild("core"))         # 7개 전부
